1	import { useMemo, useState } from 'react';
2	import { Link, useSearchParams } from 'react-router-dom';
3	import { CompraParceladaForm } from '../components/CompraParceladaForm';
4	import { LimiteCartaoBarra } from '../components/LimiteCartaoBarra';
5	import { PagamentoFaturaForm } from '../components/PagamentoFaturaForm';
6	import { Alerta, Botao, CampoSelect, CampoTexto, Cartao, EstadoVazio, TituloPagina, Valor } from '../components/ui';
7	import {
8	  cartoesAtivos,
9	  cicloFatura,
10	  criarCompraParcelada,
11	  excluirPagamento,
12	  limiteCartao,
13	  mesFaturaAberta,
14	  registrarPagamento,
15	  resumoFatura,
16	  type SituacaoFatura,
17	} from '../domain/cartoes';
18	import { formatarData, hojeISO, mesValido, nomeMes, somarMeses } from '../domain/date';
19	import { formatarMoeda } from '../domain/money';
20	import { useEstado, useStore } from '../state/store';
21	import './CartoesPage.css';
22	
23	const ROTULO_SITUACAO: Record<SituacaoFatura, string> = { aberta: 'Aberta', fechada: 'Fechada', paga: 'Paga' };
24	const COR_SITUACAO: Record<SituacaoFatura, string> = {
25	  aberta: 'cartoes__situacao--aberta',
26	  fechada: 'cartoes__situacao--fechada',
27	  paga: 'cartoes__situacao--paga',
28	};
29	
30	export function CartoesPage() {
31	  const store = useStore();
32	  const estado = useEstado();
33	  const [params, setParams] = useSearchParams();
34	  const [erro, setErro] = useState<string | null>(null);
35	  const hoje = hojeISO();
36	
37	  const cartoes = cartoesAtivos(estado.contas);
38	  const escolhido = cartoes.find((c) => c.id === params.get('cartao')) ?? cartoes[0];
39	  const mesParam = params.get('mes') ?? '';
40	  const mes = mesValido(mesParam) ? mesParam : escolhido?.cartao ? mesFaturaAberta(escolhido.cartao, hoje) : hoje.slice(0, 7);
41	
42	  const resumo = useMemo(() => (escolhido ? resumoFatura(estado, escolhido, mes, hoje) : null), [estado, escolhido, mes, hoje]);
43	  const limite = useMemo(() => (escolhido ? limiteCartao(estado, escolhido) : null), [estado, escolhido]);
44	  const categorias = new Map(estado.categorias.map((c) => [c.id, c.nome]));
45	  const pagamentos = estado.pagamentosFatura.filter((p) => escolhido && p.contaCartaoId === escolhido.id && p.mesFatura === mes);
46	  const contasOrigem = estado.contas.filter((c) => !c.arquivada && c.tipo !== 'cartao');
47	  const nomeConta = new Map(estado.contas.map((c) => [c.id, c.nome]));
48	
49	  const navegar = (parcial: Record<string, string>) => setParams({ ...(escolhido ? { cartao: escolhido.id } : {}), mes, ...parcial }, { replace: true });
50	
51	  if (!escolhido) {
52	    return (
53	      <div>
54	        <TituloPagina>Cartões</TituloPagina>
55	        <EstadoVazio titulo="Nenhum cartão de crédito" acao={<Link to="/contas" className="cartoes__link">Criar um cartão em Contas</Link>}>
56	          Cadastre uma conta do tipo cartão de crédito para acompanhar faturas, limite e parcelas.
57	        </EstadoVazio>
58	      </div>
59	    );
60	  }
61	
62	  return (
63	    <div>
64	      <TituloPagina>Cartões</TituloPagina>
65	      <div className="cartoes">
66	        {erro ? <Alerta>{erro}</Alerta> : null}
67	        <Cartao>
68	          <div className="cartoes__seletor">
69	            <CampoSelect label="Cartão" value={escolhido.id} onChange={(e) => setParams({ cartao: e.target.value })}>
70	              {cartoes.map((c) => (
71	                <option key={c.id} value={c.id}>
72	                  {c.nome}
73	                </option>
74	              ))}
75	            </CampoSelect>
76	          </div>
77	        </Cartao>
78	
79	        {!escolhido.cartao || !resumo || !limite ? (
80	          <EstadoVazio titulo="Cartão sem ciclo configurado" acao={<Link to="/contas" className="cartoes__link">Configurar em Contas</Link>}>
81	            Edite a conta "{escolhido.nome}" e informe o dia de fechamento, o dia de vencimento e o limite.
82	          </EstadoVazio>
83	        ) : (
84	          <>
85	            <Cartao titulo="Limite">
86	              <LimiteCartaoBarra limite={limite} total={escolhido.cartao.limite} />
87	            </Cartao>
88	
89	            <Cartao>
90	              <div className="cartoes__navegacao">
91	                <Botao variante="secundario" onClick={() => navegar({ mes: somarMeses(mes, -1) })}>
92	                  Fatura anterior
93	                </Botao>
94	                <div className="cartoes__campo-mes">
95	                  <CampoTexto label="Mês da fatura" type="month" value={mes} onChange={(e) => mesValido(e.target.value) && navegar({ mes: e.target.value })} />
96	                </div>
97	                <Botao variante="secundario" onClick={() => navegar({ mes: somarMeses(mes, 1) })}>
98	                  Próxima fatura
99	                </Botao>
100	              </div>
101	            </Cartao>
102	
103	            <Cartao
104	              titulo={`Fatura de ${nomeMes(mes)}`}
105	              acoes={
106	                <span className={`cartoes__situacao ${COR_SITUACAO[resumo.situacao]}`} data-testid="situacao">
107	                  {ROTULO_SITUACAO[resumo.situacao]}
108	                </span>
109	              }
110	            >
111	              <p className="cartoes__ciclo" data-testid="ciclo">
112	                Ciclo de {formatarData(cicloFatura(escolhido.cartao, mes).inicio)} a {formatarData(cicloFatura(escolhido.cartao, mes).fim)} · vence em{' '}
113	                <span data-testid="vencimento">{formatarData(resumo.vencimento)}</span>
114	              </p>
115	              <dl className="cartoes__fatura-resumo">
116	                <div>
117	                  <dt>Total da fatura</dt>
118	                  <dd className="cartoes__fatura-total" data-testid="fatura-total">{formatarMoeda(resumo.total)}</dd>
119	                </div>
120	                <div>
121	                  <dt>Pago</dt>
122	                  <dd data-testid="fatura-pago">{formatarMoeda(resumo.pago)}</dd>
123	                </div>
124	                <div>
125	                  <dt>Restante</dt>
126	                  <dd data-testid="fatura-restante">{formatarMoeda(resumo.restante)}</dd>
127	                </div>
128	              </dl>
129	              {resumo.transacoes.length === 0 ? (
130	                <p className="cartoes__texto-mudo">Nenhuma compra neste ciclo.</p>
131	              ) : (
132	                <ul className="cartoes__lista" aria-label="Compras da fatura">
133	                  {resumo.transacoes.map((t) => (
134	                    <li key={t.id} className="cartoes__item">
135	                      <span className="cartoes__item-texto">
136	                        <span className="cartoes__item-titulo">{t.descricao || 'Sem descrição'}</span>
137	                        <span className="cartoes__item-detalhe">
138	                          {formatarData(t.data)} · {categorias.get(t.categoriaId) ?? 'Sem categoria'}
139	                        </span>
140	                      </span>
141	                      <Valor centavos={t.tipo === 'despesa' ? -t.valor : t.valor} texto={formatarMoeda(t.tipo === 'despesa' ? -t.valor : t.valor)} />
142	                    </li>
143	                  ))}
144	                </ul>
145	              )}
146	            </Cartao>
147	
148	            <Cartao titulo="Pagamentos desta fatura">
149	              {pagamentos.length > 0 ? (
150	                <ul className="cartoes__lista cartoes__lista--espaco" aria-label="Pagamentos registrados">
151	                  {pagamentos.map((p) => (
152	                    <li key={p.id} className="cartoes__item">
153	                      <span>
154	                        {formatarData(p.data)} · de {nomeConta.get(p.contaOrigemId) ?? 'conta removida'} · {formatarMoeda(p.valor)}
155	                      </span>
156	                      <Botao
157	                        variante="secundario"
158	                        aria-label={`Excluir pagamento de ${formatarData(p.data)}`}
159	                        onClick={() => setErro(store.aplicar((s) => excluirPagamento(s, p.id)).ok ? null : 'Não foi possível excluir o pagamento.')}
160	                      >
161	                        Excluir
162	                      </Botao>
163	                    </li>
164	                  ))}
165	                </ul>
166	              ) : null}
167	              {resumo.restante > 0 ? (
168	                <PagamentoFaturaForm
169	                  key={`${escolhido.id}-${mes}-${resumo.restante}`}
170	                  contaCartaoId={escolhido.id}
171	                  mesFatura={mes}
172	                  restante={resumo.restante}
173	                  contasOrigem={contasOrigem}
174	                  onSalvar={(dados) => store.aplicar((s) => registrarPagamento(s, dados, hoje))}
175	                />
176	              ) : (
177	                <p className="cartoes__texto-mudo">Não há valor a pagar nesta fatura.</p>
178	              )}
179	            </Cartao>
180	
181	            <Cartao titulo="Compra parcelada">
182	              <CompraParceladaForm contaId={escolhido.id} categorias={estado.categorias} onSalvar={(dados) => store.aplicar((s) => criarCompraParcelada(s, dados))} />
183	            </Cartao>
184	          </>
185	        )}
186	      </div>
187	    </div>
188	  );
189	}
