1	import { useMemo, useState } from 'react';
2	import { Alerta, Botao, Cartao, EstadoVazio, TituloPagina, Valor } from '../components/ui';
3	import { ConfirmDialog } from '../components/ConfirmDialog';
4	import { ContaForm } from '../components/ContaForm';
5	import {
6	  ROTULO_TIPO_CONTA,
7	  arquivarConta,
8	  contaTemTransacoes,
9	  criarConta,
10	  editarConta,
11	  excluirConta,
12	  ordenarContas,
13	  reativarConta,
14	  saldoTotal,
15	  saldosPorConta,
16	  type DadosConta,
17	} from '../domain/contas';
18	import { formatarMoeda } from '../domain/money';
19	import type { Conta } from '../domain/types';
20	import { useEstado, useStore } from '../state/store';
21	import './ContasPage.css';
22	
23	export function ContasPage() {
24	  const store = useStore();
25	  const estado = useEstado();
26	  const [criando, setCriando] = useState(false);
27	  const [editandoId, setEditandoId] = useState<string | null>(null);
28	  const [excluindo, setExcluindo] = useState<Conta | null>(null);
29	  const [erro, setErro] = useState<string | null>(null);
30	
31	  const saldos = useMemo(() => saldosPorConta(estado), [estado]);
32	  const total = useMemo(() => saldoTotal(estado), [estado]);
33	  const ativas = ordenarContas(estado.contas.filter((c) => !c.arquivada));
34	  const arquivadas = ordenarContas(estado.contas.filter((c) => c.arquivada));
35	
36	  const executar = (op: Parameters<typeof store.aplicar>[0]) => {
37	    const r = store.aplicar(op);
38	    setErro(r.ok ? null : r.erro);
39	    return r;
40	  };
41	
42	  const linha = (conta: Conta) => {
43	    const saldo = saldos.get(conta.id) ?? 0;
44	    const temTransacoes = contaTemTransacoes(estado, conta.id);
45	    if (editandoId === conta.id) {
46	      return (
47	        <li key={conta.id} className="contas__linha contas__linha--edicao">
48	          <ContaForm
49	            inicial={conta}
50	            onCancelar={() => setEditandoId(null)}
51	            onSalvar={(dados: DadosConta) => {
52	              const r = store.aplicar((s) => editarConta(s, conta.id, dados));
53	              if (r.ok) setEditandoId(null);
54	              return r;
55	            }}
56	          />
57	        </li>
58	      );
59	    }
60	    return (
61	      <li key={conta.id} className="contas__linha">
62	        <div className="contas__info">
63	          <p className="contas__nome">{conta.nome}</p>
64	          <p className="contas__tipo">{ROTULO_TIPO_CONTA[conta.tipo]}</p>
65	        </div>
66	        <div className="contas__acoes">
67	          <Valor centavos={saldo} texto={formatarMoeda(saldo)} />
68	          <Botao variante="secundario" aria-label={`Editar ${conta.nome}`} onClick={() => setEditandoId(conta.id)}>
69	            Editar
70	          </Botao>
71	          {conta.arquivada ? (
72	            <Botao variante="secundario" aria-label={`Reativar ${conta.nome}`} onClick={() => executar((s) => reativarConta(s, conta.id))}>
73	              Reativar
74	            </Botao>
75	          ) : (
76	            <Botao variante="secundario" aria-label={`Arquivar ${conta.nome}`} onClick={() => executar((s) => arquivarConta(s, conta.id))}>
77	              Arquivar
78	            </Botao>
79	          )}
80	          {!temTransacoes ? (
81	            <Botao variante="perigo" aria-label={`Excluir ${conta.nome}`} onClick={() => setExcluindo(conta)}>
82	              Excluir
83	            </Botao>
84	          ) : null}
85	        </div>
86	      </li>
87	    );
88	  };
89	
90	  return (
91	    <div>
92	      <TituloPagina acoes={!criando ? <Botao onClick={() => setCriando(true)}>Nova conta</Botao> : undefined}>Contas</TituloPagina>
93	      <div className="contas__pilha">
94	        {erro ? <Alerta>{erro}</Alerta> : null}
95	        {criando ? (
96	          <Cartao titulo="Nova conta">
97	            <ContaForm
98	              onCancelar={() => setCriando(false)}
99	              onSalvar={(dados) => {
100	                const r = store.aplicar((s) => criarConta(s, dados));
101	                if (r.ok) setCriando(false);
102	                return r;
103	              }}
104	            />
105	          </Cartao>
106	        ) : null}
107	
108	        {ativas.length === 0 && !criando ? (
109	          <EstadoVazio titulo="Nenhuma conta ainda" acao={<Botao onClick={() => setCriando(true)}>Crie sua primeira conta</Botao>}>
110	            Contas são os lugares onde seu dinheiro está: banco, carteira, cartão. Toda transação pertence a uma conta.
111	          </EstadoVazio>
112	        ) : null}
113	
114	        {ativas.length > 0 ? (
115	          <>
116	            <Cartao titulo="Saldo total">
117	              <p className="contas__total">
118	                <Valor centavos={total.total} texto={formatarMoeda(total.total)} data-testid="saldo-total" />
119	              </p>
120	              <dl className="contas__resumo">
121	                <div>
122	                  <dt>Contas</dt>
123	                  <dd data-testid="saldo-contas">{formatarMoeda(total.contas)}</dd>
124	                </div>
125	                <div>
126	                  <dt>Cartões (fatura em aberto)</dt>
127	                  <dd data-testid="saldo-cartoes">{formatarMoeda(total.cartoes)}</dd>
128	                </div>
129	              </dl>
130	            </Cartao>
131	            <Cartao titulo="Contas ativas">
132	              <ul className="contas__lista">{ativas.map(linha)}</ul>
133	            </Cartao>
134	          </>
135	        ) : null}
136	
137	        {arquivadas.length > 0 ? (
138	          <Cartao titulo="Contas arquivadas">
139	            <ul className="contas__lista">{arquivadas.map(linha)}</ul>
140	          </Cartao>
141	        ) : null}
142	      </div>
143	
144	      {excluindo ? (
145	        <ConfirmDialog
146	          titulo="Excluir conta?"
147	          mensagem={`A conta "${excluindo.nome}" será excluída definitivamente.`}
148	          rotuloConfirmar="Excluir"
149	          perigo
150	          onCancelar={() => setExcluindo(null)}
151	          onConfirmar={() => {
152	            executar((s) => excluirConta(s, excluindo.id));
153	            setExcluindo(null);
154	          }}
155	        />
156	      ) : null}
157	    </div>
158	  );
159	}
