1	import { useMemo, useRef, useState, type DragEvent } from 'react';
2	import { Link } from 'react-router-dom';
3	import { CsvMapeamento } from '../components/CsvMapeamento';
4	import { CsvPrevia, type LinhaPrevia } from '../components/CsvPrevia';
5	import { Alerta, Botao, Cartao, CampoSelect, EstadoVazio, TituloPagina } from '../components/ui';
6	import {
7	  adivinharMapeamento,
8	  decodificar,
9	  desfazerImportacao,
10	  detectarSeparador,
11	  importarTransacoes,
12	  interpretarLinhas,
13	  marcarDuplicatas,
14	  parseCsv,
15	  sugerirCategoria,
16	  sugerirTags,
17	  validarArquivo,
18	} from '../domain/csv';
19	import { hojeISO } from '../domain/date';
20	import type { MapeamentoCsv } from '../domain/types';
21	import { lerArquivoBuffer } from '../lib/download';
22	import { useEstado, useStore } from '../state/store';
23	import './ImportarCsvPage.css';
24	
25	interface Resumo {
26	  importacaoId: string;
27	  importadas: number;
28	  ignoradas: number;
29	  comErro: number;
30	}
31	
32	export function ImportarCsvPage() {
33	  const store = useStore();
34	  const estado = useEstado();
35	  const contasAtivas = estado.contas.filter((c) => !c.arquivada);
36	
37	  const [contaId, setContaId] = useState('');
38	  const contaEfetiva = contasAtivas.some((c) => c.id === contaId) ? contaId : (contasAtivas[0]?.id ?? '');
39	  const [nomeArquivo, setNomeArquivo] = useState<string | null>(null);
40	  const [linhasCsv, setLinhasCsv] = useState<string[][] | null>(null);
41	  const [mapeamento, setMapeamento] = useState<MapeamentoCsv | null>(null);
42	  const [selecao, setSelecao] = useState<Record<number, boolean>>({});
43	  const [categoriasEscolhidas, setCategoriasEscolhidas] = useState<Record<number, string>>({});
44	  const [erro, setErro] = useState<string | null>(null);
45	  const [resumo, setResumo] = useState<Resumo | null>(null);
46	  const [arrastando, setArrastando] = useState(false);
47	  const entrada = useRef<HTMLInputElement>(null);
48	
49	  const ultimaImportacao = estado.importacoes[estado.importacoes.length - 1];
50	
51	  const reiniciar = () => {
52	    setNomeArquivo(null);
53	    setLinhasCsv(null);
54	    setMapeamento(null);
55	    setSelecao({});
56	    setCategoriasEscolhidas({});
57	  };
58	
59	  const carregarArquivo = async (arquivo: File | undefined) => {
60	    if (!arquivo) return;
61	    setErro(null);
62	    setResumo(null);
63	    const valido = validarArquivo(arquivo.name, arquivo.size);
64	    if (!valido.ok) {
65	      reiniciar();
66	      setErro(valido.erro);
67	      return;
68	    }
69	    try {
70	      const texto = decodificar(new Uint8Array(await lerArquivoBuffer(arquivo)));
71	      const linhas = parseCsv(texto, detectarSeparador(texto));
72	      if (linhas.length === 0) {
73	        reiniciar();
74	        setErro('O arquivo está vazio.');
75	        return;
76	      }
77	      const lembrado = estado.mapeamentosCsv[contaEfetiva];
78	      const colunas = Math.max(...linhas.map((l) => l.length));
79	      const aproveitavel = lembrado && [lembrado.colData, lembrado.colDescricao, lembrado.colValor, lembrado.colCredito, lembrado.colDebito].every((c) => c === null || c < colunas);
80	      setLinhasCsv(linhas);
81	      setMapeamento(aproveitavel ? lembrado : adivinharMapeamento(linhas));
82	      setNomeArquivo(arquivo.name);
83	      setSelecao({});
84	      setCategoriasEscolhidas({});
85	    } catch (e) {
86	      reiniciar();
87	      setErro(e instanceof Error ? e.message : 'Não foi possível ler o arquivo.');
88	    }
89	  };
90	
91	  const linhas: LinhaPrevia[] = useMemo(() => {
92	    if (!linhasCsv || !mapeamento) return [];
93	    const interpretadas = interpretarLinhas(linhasCsv, mapeamento);
94	    const duplicadas = marcarDuplicatas(interpretadas, estado, contaEfetiva);
95	    return interpretadas.map((l) => {
96	      const duplicata = duplicadas.has(l.indice);
97	      return {
98	        ...l,
99	        duplicata,
100	        selecionada: l.erro ? false : (selecao[l.indice] ?? !duplicata),
101	        categoriaId: l.erro ? undefined : (categoriasEscolhidas[l.indice] ?? sugerirCategoria(estado, l.descricao, l.tipo)),
102	        tags: l.erro ? [] : sugerirTags(estado, l.descricao, l.tipo),
103	      };
104	    });
105	  }, [linhasCsv, mapeamento, estado, contaEfetiva, selecao, categoriasEscolhidas]);
106	
107	  const aImportar = linhas.filter((l) => l.selecionada);
108	  const comErro = linhas.filter((l) => l.erro).length;
109	  const ignoradas = linhas.length - aImportar.length - comErro;
110	
111	  const confirmar = () => {
112	    if (!mapeamento) return;
113	    const itens = aImportar.map((l) => ({ data: l.data!, descricao: l.descricao, valor: l.valor, tipo: l.tipo, categoriaId: l.categoriaId ?? '', tags: l.tags }));
114	    let criada = '';
115	    const r = store.aplicar((s) => {
116	      const imp = importarTransacoes(s, contaEfetiva, itens, mapeamento, hojeISO());
117	      if (!imp.ok) return imp;
118	      criada = imp.valor.importacao.id;
119	      return { ok: true, valor: imp.valor.estado };
120	    });
121	    if (!r.ok) {
122	      setErro(r.erro);
123	      return;
124	    }
125	    setErro(null);
126	    setResumo({ importacaoId: criada, importadas: itens.length, ignoradas, comErro });
127	    reiniciar();
128	  };
129	
130	  const desfazer = (id: string) => {
131	    const r = store.aplicar((s) => desfazerImportacao(s, id));
132	    if (!r.ok) return setErro(r.erro);
133	    setErro(null);
