14	export function ContaForm({ inicial, onSalvar, onCancelar }: Props) {
15	  const [nome, setNome] = useState(inicial?.nome ?? '');
16	  const [tipo, setTipo] = useState<TipoConta>(inicial?.tipo ?? 'corrente');
17	  const [saldo, setSaldo] = useState(inicial ? valorParaCampo(inicial.saldoInicial) : '');
18	  const [fechamento, setFechamento] = useState(inicial?.cartao ? String(inicial.cartao.diaFechamento) : '');
19	  const [vencimento, setVencimento] = useState(inicial?.cartao ? String(inicial.cartao.diaVencimento) : '');
20	  const [limite, setLimite] = useState(inicial?.cartao ? valorParaCampo(inicial.cartao.limite) : '');
21	  const [erros, setErros] = useState<Record<'nome' | 'saldo' | 'geral' | 'diaFechamento' | 'diaVencimento' | 'limite', string | undefined>>({
22	    nome: undefined, saldo: undefined, geral: undefined, diaFechamento: undefined, diaVencimento: undefined, limite: undefined,
23	  });
24	  const semErros = { nome: undefined, saldo: undefined, geral: undefined, diaFechamento: undefined, diaVencimento: undefined, limite: undefined };
25	
26	  const enviar = (e: FormEvent) => {
27	    e.preventDefault();
28	    const saldoInicial = saldo.trim() === '' ? 0 : parseValor(saldo);
29	    if (saldoInicial === null) {
30	      setErros({ ...semErros, saldo: 'Informe um valor válido, como 1.234,56 ou -50,00.' });
31	      return;
32	    }
33	    // Ciclo do cartão é tudo ou nada: se qualquer campo foi preenchido, todos são validados.
34	    const preencheuCartao = tipo === 'cartao' && [fechamento, vencimento, limite].some((v) => v.trim() !== '');
35	    const limiteCentavos = parseValor(limite);
