37	      ? { diaFechamento: Number(fechamento), diaVencimento: Number(vencimento), limite: limiteCentavos ?? Number.NaN }
38	      : undefined;
39	    const r = onSalvar({ nome, tipo, saldoInicial, cartao });
40	    if (!r.ok) {
41	      const campo = r.campo as keyof typeof semErros | undefined;
42	      setErros(campo && campo in semErros ? { ...semErros, [campo]: r.erro } : { ...semErros, geral: r.erro });
43	    }
44	  };
